// ============================================================================
// PRODUCTION-READY GOOGLE SHEETS BATCH UPDATE WITH CREATE SUPPORT
// ============================================================================

// --- Configuration ---
const CONFIG = {
  sheetName: 'מסמכים נכנסים',
  idColumn: 'ID',
  maxUpdatesPerBatch: 500,
  validateHeaders: true,
  strictMode: true,
  matchingFields: {
    primary: ['COMPANY_ID', 'COMPANY_DOC_ID'],
    secondary: 'HASH'
  }
};

// --- Helper Functions ---

function columnToLetter(column) {
  if (column < 0) {
    throw new Error(`Invalid column index: ${column}`);
  }

  let letter = '';
  let temp = column;

  while (temp >= 0) {
    letter = String.fromCharCode((temp % 26) + 65) + letter;
    temp = Math.floor(temp / 26) - 1;
  }

  return letter;
}

function validateColumns(headerMap, updateItems) {
  const errors = [];
  const requiredColumns = new Set();

  updateItems.forEach(item => {
    Object.keys(item).forEach(key => requiredColumns.add(key));
  });

  requiredColumns.forEach(col => {
    if (col !== CONFIG.idColumn && headerMap[col] === undefined) {
      errors.push(`Column "${col}" not found in sheet headers`);
    }
  });

  return errors;
}

function formatErrors(errors) {
  return errors.map((err, idx) => `${idx + 1}. ${err}`).join('\n');
}

function sanitizeValueForSheets(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return value;
}

function generateUniqueId() {
  const timestamp = Date.now();
  const random = Math.floor(Math.random() * 1000000000).toString(36);
  return `${timestamp}${random}`;
}

function matchByFields(item, rowIndex, fields) {
  // Check if all fields are present and not empty in the item
  const hasAllFields = fields.every(field => {
    const value = item[field];
    return value !== undefined && value !== null && value !== '' && 
           value?.toLowerCase() !== 'unknown';
  });

  if (!hasAllFields) return null;

  // Try to find a matching row
  for (const [id, row] of rowIndex.entries()) {
    const matches = fields.every(field => {
      const itemValue = String(item[field] || '').toLowerCase();
      const rowValue = String(row[field] || '').toLowerCase();
      return itemValue === rowValue && itemValue !== '';
    });

    if (matches) {
      return row;
    }
  }

  return null;
}

// ============================================================================
// MAIN EXECUTION
// ============================================================================

try {
  // --- Step 1: Get Input Data ---
  const sheetDataRows = $("Get Sheet Data").all().map(item => item.json);
  const updateItems = $('Start').all().map(i => i.json);

  console.log(`Processing ${updateItems.length} item(s)`);

  // --- Step 2: Validate Sheet Data ---
  if (!sheetDataRows || sheetDataRows.length === 0) {
    return [{
      json: {
        success: false,
        updateCount: 0,
        createCount: 0,
        error: 'Sheet data is empty',
        data: []
      }
    }];
  }

  // --- Step 3: Build Header Map ---
  const headers = Object.keys(sheetDataRows[0]).filter(k => k !== "row_number");

  if (!headers.includes(CONFIG.idColumn)) {
    throw new Error(`ID column "${CONFIG.idColumn}" not found in sheet headers`);
  }

  const headerMap = {};
  headers.forEach((header, index) => {
    headerMap[header] = index;
  });

  console.log(`Found ${headers.length} columns in sheet`);

  // --- Step 4: Validate Update Items ---
  if (!updateItems || updateItems.length === 0) {
    return [{
      json: {
        success: true,
        updateCount: 0,
        createCount: 0,
        message: 'No items provided',
        data: []
      }
    }];
  }

  if (CONFIG.validateHeaders) {
    const columnErrors = validateColumns(headerMap, updateItems);
    if (columnErrors.length > 0) {
      throw new Error(`Column validation failed:\n${formatErrors(columnErrors)}`);
    }
  }

  // --- Step 5: Build Row Index for Fast Lookup ---
  const rowIndex = new Map();
  sheetDataRows.forEach(row => {
    const id = row[CONFIG.idColumn];
    if (id !== undefined && id !== null && id !== '') {
      rowIndex.set(String(id), row);
    }
  });

  console.log(`Indexed ${rowIndex.size} rows by ${CONFIG.idColumn}`);

  // --- Step 6: Process Updates and Creates ---
  const batchUpdates = [];
  const newRows = [];
  const errors = [];
  const warnings = [];
  const processedIds = new Set();
  const stats = {
    itemsProcessed: 0,
    rowsUpdated: 0,
    rowsCreated: 0,
    cellsUpdated: 0,
    skippedNoChange: 0,
    duplicateIds: 0,
    matchedByCompany: 0,
    matchedByHash: 0
  };

  for (const itemData of updateItems) {
    stats.itemsProcessed++;
    let searchId = itemData[CONFIG.idColumn];
    let foundRow = null;
    let matchMethod = null;

    // Try to find existing row
    if (searchId !== undefined && searchId !== null && searchId !== '') {
      // Has ID - direct lookup
      const searchIdStr = String(searchId);
      foundRow = rowIndex.get(searchIdStr);
      matchMethod = 'id';

      if (processedIds.has(searchIdStr)) {
        stats.duplicateIds++;
        warnings.push(`Duplicate ID "${searchId}" in batch (processing latest)`);
      }
      processedIds.add(searchIdStr);
    } else {
      // No ID - try matching by COMPANY_ID + COMPANY_DOC_ID
      foundRow = matchByFields(itemData, rowIndex, CONFIG.matchingFields.primary);
      if (foundRow) {
        matchMethod = 'company';
        stats.matchedByCompany++;
        searchId = foundRow[CONFIG.idColumn];
      } else if (itemData[CONFIG.matchingFields.secondary]) {
        // Try matching by HASH
        foundRow = matchByFields(itemData, rowIndex, [CONFIG.matchingFields.secondary]);
        if (foundRow) {
          matchMethod = 'hash';
          stats.matchedByHash++;
          searchId = foundRow[CONFIG.idColumn];
        }
      }
    }

    // If row found - UPDATE
    if (foundRow) {
      const googleSheetRowNumber = foundRow.row_number;
      if (!googleSheetRowNumber) {
        errors.push(`Row with ID "${searchId}" is missing 'row_number' property`);
        if (CONFIG.strictMode) break;
        continue;
      }

      let rowHasUpdates = false;

      for (const [fieldName, newValue] of Object.entries(itemData)) {
        if (fieldName === CONFIG.idColumn) continue;

        const columnIndex = headerMap[fieldName];
        if (columnIndex === undefined) {
          if (CONFIG.strictMode) {
            errors.push(`Column "${fieldName}" not found for ID "${searchId}"`);
            break;
          }
          warnings.push(`Column "${fieldName}" not found - skipping`);
          continue;
        }

        const sanitizedNewValue = sanitizeValueForSheets(newValue);
        const currentValue = foundRow[fieldName];
        const sanitizedCurrentValue = sanitizeValueForSheets(currentValue);

        const currentStr = String(sanitizedCurrentValue);
        const newStr = String(sanitizedNewValue);

        if (currentStr === newStr) {
          stats.skippedNoChange++;
          continue;
        }

        const cellLetter = columnToLetter(columnIndex);
        const cellAddress = `${cellLetter}${googleSheetRowNumber}`;

        console.log(`[${searchId}/${matchMethod}] ${fieldName} @ ${cellAddress}: "${currentValue}" → "${newValue}"`);

        batchUpdates.push({
          range: `${CONFIG.sheetName}!${cellAddress}`,
          values: [[sanitizedNewValue]]
        });

        stats.cellsUpdated++;
        rowHasUpdates = true;
      }

      if (rowHasUpdates) {
        stats.rowsUpdated++;
      }
    } 
    // If row not found - CREATE
    else {
      const newId = generateUniqueId();
      const newRow = { ...itemData, [CONFIG.idColumn]: newId };

      // Build complete row with all columns
      const rowValues = headers.map(header => {
        const value = newRow[header];
        return sanitizeValueForSheets(value);
      });

      newRows.push(rowValues);
      stats.rowsCreated++;

      console.log(`[CREATE] New row with ID: ${newId}`);
    }

    if (CONFIG.strictMode && errors.length > 0) {
      break;
    }
  }

  // --- Step 7: Check for Errors ---
  if (errors.length > 0) {
    console.error('ERRORS:', formatErrors(errors));
    return [{
      json: {
        success: false,
        updateCount: 0,
        createCount: 0,
        error: `${errors.length} error(s) occurred:\n${formatErrors(errors)}`,
        warnings: warnings.length > 0 ? warnings : undefined,
        stats,
        data: []
      }
    }];
  }

  // --- Step 8: Check Batch Size Limit ---
  const totalOperations = batchUpdates.length + newRows.length;
  if (totalOperations > CONFIG.maxUpdatesPerBatch) {
    return [{
      json: {
        success: false,
        updateCount: 0,
        createCount: 0,
        error: `Total operations (${totalOperations}) exceeds limit (${CONFIG.maxUpdatesPerBatch})`,
        suggestion: 'Split into smaller batches',
        stats,
        data: []
      }
    }];
  }

  // --- Step 9: Separate updates and appends ---
  // batchUpdate can only update existing cells
  // New rows must use append API
  const appendData = newRows.length > 0 ? [{
    range: `${CONFIG.sheetName}`,
    values: newRows
  }] : [];

  // --- Step 10: Return Results ---
  const result = {
    success: true,
    updateCount: batchUpdates.length,
    createCount: newRows.length,
    hasUpdates: batchUpdates.length > 0,
    hasAppends: newRows.length > 0,
    message: (batchUpdates.length === 0 && newRows.length === 0)
      ? 'No operations needed'
      : `Prepared ${batchUpdates.length} cell update(s) and ${newRows.length} new row(s)`,
    stats: {
      ...stats,
      warnings: warnings.length
    },
    warnings: warnings.length > 0 ? warnings : undefined,
    data: batchUpdates,
    appendData: appendData,
    valueInputOption: "RAW"
  };

  console.log('\n=== OPERATION SUMMARY ===');
  console.log(`Items processed: ${stats.itemsProcessed}`);
  console.log(`Rows updated: ${stats.rowsUpdated}`);
  console.log(`Rows created: ${stats.rowsCreated}`);
  console.log(`Cells updated: ${stats.cellsUpdated}`);
  console.log(`Matched by company: ${stats.matchedByCompany}`);
  console.log(`Matched by hash: ${stats.matchedByHash}`);
  console.log(`Skipped (no change): ${stats.skippedNoChange}`);
  if (warnings.length > 0) {
    console.log(`Warnings: ${warnings.length}`);
  }

  return [{ json: result }];

} catch (error) {
  console.error('FATAL ERROR:', error.message);
  console.error('Stack trace:', error.stack);

  return [{
    json: {
      success: false,
      updateCount: 0,
      createCount: 0,
      error: `Fatal error: ${error.message}`,
      errorType: error.name,
      data: []
    }
  }];
}

// --- Process Update Request ---
// This code validates the incoming data and prepares it for the 'Update Row' operation.

const body = $json.body || $json;

// 1. Validate that the lookup key (ID) is present
if (!body.ID) {
  throw new Error('Validation failed: Missing required field `ID` in the request body.');
}

// 2. Construct the object of fields to update
// This ensures only provided fields are sent for update.
const updateData = {};
const allowedKeys = [
  "ID",
  "NAME",
  "COMPANY_ID",
  "SHORT_DOC_ID",
  "TYPE",
  "STATUS",
  "COMPANY_DOC_ID",
  "LINK",
  "DOC_DATE",
  "PURCHASE_ID",
  "SHIPMENT_DOC_ID",
  "LINKED_BS",
  "BS_LINE_DATE",
  "BS_LINE_AMOUNT",
  "DOC_TOTAL_AMOUNT",
  "DOC_TOTAL_AMOUNT_COMPLETED",
  "SOURCE_TYPE",
  "SOURCE_ID",
  "SOURCE_LINK",
  "SIZE",
  "HASH",
  "TIMESTAMP",
  "COMPANY_NAME",
  "REQUIRED_ACTION",
  "BS_EXTRACTED_LINES",
  "TOTAL_AMOUNT",
  "BS_EXTRACTION_VERIFIED",
  "BS_LINE_NOTE",
  "FROM_OFFICE",
  "FROM_OFFICE_CHECK",
  "BS_LINK_DOCUMENTS_COMPLETED",
  "SEARCH_IN_DRIVE_COMPLETED",
  "DOC_DATE_COMPLETED",
  "PURCHASE_ID_COMPLETED",
  "SHIPMENT_ID_COMPLETED",
  "COMPANY_NAME_COMPLETED",
  "API_TOOLS_ID_COMPLETED",
  "API_TOOLS_ID",
  "EMPTY",
  "BS_EXTRACTED_LINES_COMPLETED",
  "BS_EXTRACTION_USE_CACHE",
  "EX_INVOICE_ID",
  "INVOICE_ID_COMPLETED",
  "EX_IS_BS_COMPLETED",
  "EX_IS_BS",
  "FIGURE_TYPE_COMPLETED",
  "DOUBLE_LINE_CONTEXT"
];

let hasUpdateField = false;
for (const key of allowedKeys) {
  if (body.hasOwnProperty(key)) {
    updateData[key] = body[key];
    hasUpdateField = true;
  }
}

if (!hasUpdateField) {
    throw new Error('Validation failed: At least one field to update must be provided.');
}

// 3. Add the lookup key and a new timestamp
updateData.ID = body.ID; // The key to find the row
updateData.TIMESTAMP = new Date().toISOString(); // Update the timestamp

// 4. Return the data for the Google Sheets node
return {
  json: updateData
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  	const cleanedObj = Object.fromEntries(
  Object.entries(item.json).filter(([key, value]) => value !== null)
);
  item.json = cleanedObj;

}

return $input.all();

var on_create_settings = $input.all()
  .map(i => i.json)
